185	func (ftr *fileTableReader) clone() (chunkSource, error) {
186		tr, err := ftr.tableReader.clone()
187		if err != nil {
188			return &fileTableReader{}, err
189		}
190		return &fileTableReader{tr, ftr.h}, nil
191	}
192	
193	type fileReaderAt struct {
194		f *os.File
195		// refcnt, clone() increments and Close() decrements. The *os.File is closed when it reaches 0.
196		cnt         *int32
197		path        string
198		sz          int64
199		mmapIndexes bool // If possible, the file reader will mmap the file for reading index data.
200	}
201	
202	func (fra *fileReaderAt) clone() (tableReaderAt, error) {
203		if !dynassert.Assert(atomic.AddInt32(fra.cnt, 1) > 1, "attempt to clone a closed fileReaderAt") {
204			// Restore previous refcnt, despite being in a weird state...
205			atomic.AddInt32(fra.cnt, -1)
206			return newFileReaderAt(fra.path, fra.mmapIndexes)
207		}
208		return &fileReaderAt{
209			f:           fra.f,
210			path:        fra.path,
211			sz:          fra.sz,
212			cnt:         fra.cnt,
213			mmapIndexes: fra.mmapIndexes,
214		}, nil
215	}
216	
217	func (fra *fileReaderAt) Close() error {
218		cnt := atomic.AddInt32(fra.cnt, -1)
219		dynassert.Assert(cnt >= 0, "invalid cnt on fileReaderAt")
220		if cnt == 0 {
221			return fra.f.Close()
222		}
223		return nil
224	}
225	
226	func (fra *fileReaderAt) Reader(ctx context.Context) (io.ReadCloser, error) {
227		return os.Open(fra.path)
228	}
229	
230	func (fra *fileReaderAt) ReadAtWithStats(ctx context.Context, p []byte, off int64, stats *Stats) (n int, err error) {
231		t1 := time.Now()
232		defer func() {
233			stats.FileBytesPerRead.Sample(uint64(len(p)))
234			stats.FileReadLatency.SampleTimeSince(t1)
235		}()
236		return fra.f.ReadAt(p, off)
237	}
238	
239	func newTableFileMetadata(path string, chunkCount uint32) (*TableFileMetadata, error) {
240		// table files can never have mmapped indexes
241		fra, err := newFileReaderAt(path, false)
242		if err != nil {
243			return nil, err
244		}
245	
246		idxSz := int64(indexSize(chunkCount) + footerSize)
247		indexOffset := fra.sz - idxSz
248	
249		return &TableFileMetadata{
250			snappyChunkCount: int(chunkCount),
251			snappyBytes:      uint64(indexOffset),
252		}, nil
253	}
