78	func (ftp *fsTablePersister) Exists(ctx context.Context, name string, chunkCount uint32, stats *Stats) (bool, error) {
79		ftp.removeMu.Lock()
80		defer ftp.removeMu.Unlock()
81		if ftp.toKeep != nil {
82			ftp.toKeep[filepath.Join(ftp.dir, name)] = struct{}{}
83		}
84	
85		if h, ok := hash.MaybeParse(name); ok {
86			exists, err := tableFileExists(ctx, ftp.dir, h)
87			if exists || err != nil {
88				return exists, err
89			}
90	
91		}
92	
93		return archiveFileExists(ctx, ftp.dir, name)
94	}
