96	func (ftp *fsTablePersister) Persist(ctx context.Context, behavior dherrors.FatalBehavior, mt *memTable, haver chunkReader, keeper keeperF, stats *Stats) (chunkSource, gcBehavior, error) {
97		t1 := time.Now()
98		defer stats.PersistLatency.SampleTimeSince(t1)
99	
100		name, data, _, chunkCount, gcb, err := mt.write(haver, keeper, stats)
101		if err != nil {
102			return emptyChunkSource{}, gcBehavior_Continue, err
103		}
104		if gcb != gcBehavior_Continue {
