119	func (ftp *fsTablePersister) CopyTableFile(_ context.Context, r io.Reader, fileId string, _ uint64, _ uint64) error {
120		tn, f, err := func() (n string, cleanup func(), err error) {
121			ftp.removeMu.Lock()
122			var temp *os.File
123			temp, err = tempfiles.MovableTempFileProvider.NewFile(ftp.dir, tempTablePrefix)
124			if err != nil {
125				ftp.removeMu.Unlock()
126				return "", func() {}, err
127			}
128			ftp.curTmps[filepath.Clean(temp.Name())] = struct{}{}
129			ftp.removeMu.Unlock()
130	
131			cleanup = func() {
132				ftp.removeMu.Lock()
133				delete(ftp.curTmps, filepath.Clean(temp.Name()))
134				ftp.removeMu.Unlock()
135			}
136	
137			defer func() {
138				cerr := temp.Close()
139				if cerr != nil {
140					err = errors.Join(err, fmt.Errorf("error Closing temp in CopyTableFile: %w", cerr))
141				}
142			}()
143	
144			_, err = io.Copy(temp, r)
145			if err != nil {
146				return "", cleanup, err
147			}
148	
149			err = temp.Sync()
150			if err != nil {
151				return "", cleanup, err
152			}
153	
154			return temp.Name(), cleanup, nil
155		}()
156		defer f()
157		if err != nil {
158			return err
159		}
160	
161		path := filepath.Join(ftp.dir, fileId)
162		ftp.removeMu.Lock()
163		if ftp.toKeep != nil {
164			ftp.toKeep[filepath.Clean(path)] = struct{}{}
165		}
166		defer ftp.removeMu.Unlock()
167		return file.Rename(tn, path)
168	}
