// refCounter is implemented by types that track reference counts on open
// table files. Implementations allow the persister to know when a file is
// still in use so that it is not deleted out from under an open reader.
type refCounter interface {
	addRef()
	decRef()
}

// noopRefCounter is a refCounter implementation that does nothing. It is used
// when reference counting is not needed (e.g., in tests or one-off reads).
type noopRefCounter struct{}

func (noopRefCounter) addRef() {}
func (noopRefCounter) decRef() {}

var _ refCounter = noopRefCounter{}

// openFileRefCounter tracks the number of open readers for a single table file
// against its owning fsTablePersister.
type openFileRefCounter struct {
	ftp  *fsTablePersister
	path string
}

func (r openFileRefCounter) addRef() { r.ftp.incOpen(r.path) }
func (r openFileRefCounter) decRef() { r.ftp.decOpen(r.path) }

var _ refCounter = openFileRefCounter{}

func newFSTablePersister(dir string, q MemoryQuotaProvider, mmapArchiveIndexes bool) tablePersister {
	return &fsTablePersister{
		q:                  q,
		curTmps:            make(map[string]struct{}),
		openFiles:          make(map[string]int),
		dir:                dir,
		mmapArchiveIndexes: mmapArchiveIndexes,
	}
}

type fsTablePersister struct {
	q MemoryQuotaProvider
	// While we are running PruneTableFiles, any newly created table files are
	// added to this map. The file delete loop will never delete anything which
	// appears in this map. Files should be added to this map before they are
	// written.
	toKeep map[string]struct{}
	// Any temp files we are currently writing are always present in this map.
	// The logic should be taken before we generate the new temp file, and the
	// new temp file should be added to this map. Care should be taken to always
	// remove the entry from this map when we are done processing the temp file
	// or else this map will grow without bound.
	curTmps map[string]struct{}
	// openFiles tracks the number of currently open readers for each table
	// file (keyed by cleaned absolute path). Any file with a positive count
	// has an open reader and must not be pruned, even if it is not in the
	// keeper set. Entries are added by Open (via openFileRefCounter.addRef)
	// and removed when the last reader is closed.
	openFiles map[string]int
	dir       string
	// Protects the toKeep, curTmps and openFiles maps.
